package model;
public class CartItem { private int cartItemId,cartId,foodId,quantity; private Food food; public CartItem(){} public CartItem(int a,int b,int c,int d){cartItemId=a;cartId=b;foodId=c;quantity=d;} public int getCartItemId(){return cartItemId;} public void setCartItemId(int v){cartItemId=v;} public int getCartId(){return cartId;} public void setCartId(int v){cartId=v;} public int getFoodId(){return foodId;} public void setFoodId(int v){foodId=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public Food getFood(){return food;} public void setFood(Food v){food=v;} public double getSubtotal(){return food==null?0:food.getPrice()*quantity;} }
